// MarketStreamingClient is the client API for MarketStreaming service.
//
// For semantics around ctx use and closing/ending streaming RPCs, please refer to https://pkg.go.dev/google.golang.org/grpc/?tab=doc#ClientConn.NewStream.
type MarketStreamingClient interface {
	// Aggregated L2 book for one coin: an immediate snapshot on subscribe, then
	// one full snapshot per coalesce window (block_number may skip on a healthy stream).
	StreamL2Book(ctx context.Context, in *L2BookRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[L2BookUpdate], error)
	// Best bid/offer for the requested coins: current top of book per coin on
	// subscribe, then a frame only when a coin's top of book changes.
	StreamBbo(ctx context.Context, in *BboRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[BboUpdate], error)
	// Incremental L2 level changes with per-coin sequence chains. Snapshot
	// entries open or reset each chain; per-window diffs follow them.
	StreamL2BookDiff(ctx context.Context, in *L2BookDiffRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[L2BookDiffUpdate], error)
	// Full L4 book for one coin: snapshot on connect, then per-block diffs.
	// A recovery snapshot can appear later and replaces the client book.
	// For decoded, typed diffs use StreamL4OrderUpdates instead.
	StreamL4Book(ctx context.Context, in *L4BookRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[L4BookUpdate], error)
	// Typed L4 order diffs (NEW/UPDATE/REMOVE) -- the decoded alternative to
	// StreamL4Book's JSON. Empty coins = all.
	StreamL4OrderUpdates(ctx context.Context, in *L4OrderUpdatesRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[L4OrderUpdate], error)
	// TP/SL trigger-order lifecycle. Empty coins and no selector = all perp
	// coins; a selector picks a whole market namespace instead.
	StreamTpslUpdates(ctx context.Context, in *TpslUpdatesRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[TpslUpdate], error)
	// Normalized trades, batched per (block, coin).
	StreamTrades(ctx context.Context, in *TradesRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[TradesUpdate], error)
	// Every fill available to the endpoint, batched per block (WS allFills parity).
	// A Fill is one party's execution with position context; a matched pair
	// is a Trade (StreamTrades).
	StreamAllFills(ctx context.Context, in *AllFillsRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[FillsUpdate], error)
	// Fills whose own account matches `user` (WS userFills parity).
	StreamUserFills(ctx context.Context, in *UserFillsRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[FillsUpdate], error)
	// Fills attributed to builder `builder` (WS builderFills parity). Fills
	// carrying no builder address never match.
	StreamBuilderFills(ctx context.Context, in *BuilderFillsRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[FillsUpdate], error)
	// Fills produced by a liquidation (WS liquidationFills parity).
	StreamLiquidationFills(ctx context.Context, in *LiquidationFillsRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[FillsUpdate], error)
	// Live OHLCV candles for one (coin, interval) (WS candle parity): the
	// current bucket's state, re-emitted on a throttled cadence while it
	// changes; a newer open_time implies the previous bucket closed, and its
	// final state is sent first. On subscribe the current bucket is sent
	// immediately when the gateway already tracks it; otherwise the first
	// frame arrives with the next execution. Candle streaming returns
	// FAILED_PRECONDITION when unavailable.
	StreamCandle(ctx context.Context, in *CandleRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[CandleUpdate], error)
	// Full perp mid-price map (default dex only), re-sent whenever any mid
	// changes (WS allMids parity); current map delivered immediately on subscribe.
	// Info-derived stream; an upstream outage appears as silence.
	StreamAllMids(ctx context.Context, in *AllMidsRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[AllMidsUpdate], error)
	// One perp coin's market context, re-sent whenever it changes (WS
	// activeAssetCtx parity); current context delivered immediately on subscribe.
	// Info-derived stream; an upstream outage appears as silence.
	StreamActiveAssetCtx(ctx context.Context, in *ActiveAssetCtxRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[ActiveAssetCtxUpdate], error)
}

